const fs=require('node:fs'),cp=require('node:child_process'),assert=require('node:assert/strict');
const {chromium}=require('<PLAYWRIGHT_MODULE>');
const root='<EASYSTUD_SOURCE_ROOT>',out=__dirname,runId='codex1-k1680-tail-f26c-native';
const ps=(file,args)=>cp.execFileSync('powershell.exe',['-NoProfile','-File','<ORCHESTRATION_SCRIPTS>/'+file,...args],{encoding:'utf8'});
const css=file=>fs.readFileSync(file,'utf8').replace(/url\((["']?)(\.\.?\/[^)"']+)\1\)/g,(m,q,relative)=>'url("'+new URL(relative,'http://localhost:8051/local/groupimport/styles/administration.css').href+'")');
async function measure(locator){return locator.evaluate(node=>{const m=n=>{const r=n.getBoundingClientRect(),s=getComputedStyle(n);return {width:r.width,height:r.height,padding:s.padding,radius:s.borderRadius,background:s.backgroundColor,border:s.border,minHeight:s.minHeight};};return {frame:m(node),parts:[...node.querySelectorAll('[class*="__loading-"]')].filter(n=>n.getClientRects().length).map(n=>({class:n.className,...m(n)}))};});}
(async()=>{
 const result={passed:false,rows:[],errors:[],runtimeFilesChanged:false};let lease=false,created=false,browser,page;
 try{
  ps('Acquire-EasyEduResourceLease.ps1',['-Resource','moodle51-perf','-ProjectNamespace','easystud','-RunId',runId,'-Repository',root,'-Purpose','K16-80 actual pending skeletons, bounded plugin AMD network pause','-LeaseSeconds','900','-OwnerPid',String(process.pid)]);lease=true;
  const fixture=JSON.parse(cp.execFileSync('<PHP_BINARY>',[out+'/fixture.php','create'],{encoding:'utf8'}));created=true;result.course=fixture.courseid;
  browser=await chromium.launch({headless:true,executablePath:'<CHROME_EXECUTABLE>'});
  for(const app of ['mass-import','administration'])for(const locale of ['fr','en'])for(const width of [1600,390]){
   const context=await browser.newContext({storageState:'<PROCESS_LOCAL_AUTH_STATE>',viewport:{width,height:1000},hasTouch:width===390,reducedMotion:'reduce'});
   let release;const gate=new Promise(resolve=>{release=resolve;}),blocked=[];
   try{
    page=await context.newPage();page.setDefaultTimeout(20000);
    page.on('pageerror',e=>result.errors.push(e.message));page.on('console',m=>{if(m.type()==='error')result.errors.push(m.text());});
    await page.route('**/lib/requirejs.php/**',route=>{blocked.push(route.request().url());return gate.then(()=>route.continue()).catch(()=>{});});
    const path=app==='mass-import'?'/local/groupimport/index.php?id='+fixture.courseid:'/admin/settings.php?section=local_groupimport';
    const pendingAmd=page.waitForRequest(request=>request.url().includes('/lib/requirejs.php/'),{timeout:12000});
    const response=await page.goto('http://localhost:8051'+path+'&lang='+locale,{waitUntil:'commit',timeout:180000});assert.equal(response.status(),200);await pendingAmd;
    const skeleton=page.locator('[data-easystud-loading-skeleton]:visible').first();await skeleton.waitFor({state:'visible',timeout:12000});
    await page.evaluate(()=>document.querySelectorAll('link[rel="stylesheet"]').forEach(n=>{if(/\/local\/groupimport\/styles\//.test(n.href))n.disabled=true;}));
    const style=await page.addStyleTag({content:css(out+'/before-'+app+'.css')});await page.evaluate(()=>document.fonts.ready);
    for(const phase of ['before','after']){
     await style.evaluate((n,value)=>{n.textContent=value;},css(phase==='before'?out+'/before-'+app+'.css':root+'/styles/'+app+'.css'));
     await skeleton.evaluate(()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve))));
     assert.ok(await skeleton.isVisible(),'Real pending skeleton remains visible during measurements');
     result.rows.push({kind:app,locale,width,phase,measurement:await measure(skeleton)});
    }
    assert.ok(blocked.length>0,'A real AMD request was held');result.networkPauses??=[];result.networkPauses.push({app,locale,width,requests:blocked.length});
   }finally{release();await page.unrouteAll({behavior:'wait'});await context.close();}
  }
  assert.equal(result.rows.length,16);for(const a of result.rows.filter(r=>r.phase==='after')){const b=result.rows.find(r=>r.phase==='before'&&r.kind===a.kind&&r.locale===a.locale&&r.width===a.width);assert.deepEqual(a.measurement,b.measurement,'Exact pending skeleton frame and footprints');assert.ok(a.measurement.parts.length>=6);}
  assert.equal(result.errors.length,0);result.passed=true;
 }catch(e){result.failure=e.message;if(page&&!page.isClosed())await page.screenshot({path:out+'/failure.png'}).catch(()=>{});}
 finally{
  if(browser)await browser.close();
  if(created)result.fixtureCleanup=JSON.parse(cp.execFileSync('<PHP_BINARY>',[out+'/fixture.php','cleanup'],{encoding:'utf8'}));
  if(lease){ps('Release-EasyEduResourceLease.ps1',['-Resource','moodle51-perf','-RunId',runId]);result.leaseReleased=true;}
  fs.writeFileSync(out+'/native.json',JSON.stringify(result,null,2));console.log(JSON.stringify({passed:result.passed,rows:result.rows.length,errors:result.errors.length,failure:result.failure,restored:result.fixtureCleanup,leaseReleased:result.leaseReleased}));
 }
})();
